import { accountApi, businessRequest, initializeBusinessPage } from './account.js';

const root = document.querySelector('#business-marketplace-app');
const officialNames = { '1on1-mutual':'1on1・相互理解', '1on1-consult':'1on1・相談', '1on1-reflect':'1on1・振り返り', 'meeting-checkin':'会議前3分', 'onboarding-day1':'新人オンボーディング 初日', 'onboarding-week1':'新人オンボーディング 1週目', 'onboarding-month1':'新人オンボーディング 1か月' };
const state = { orgId:'', user:null, workspace:null, role:'member', entitlement:null, departments:[], sets:[], official:[], tab:'catalog', editing:null, play:null, playSetup:null, count:2, error:'', status:'', busy:false, requestId:0, authBound:false };
const esc = (v='') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const admin = () => state.role === 'owner' || state.role === 'admin'; const fresh=(token)=>token===state.requestId; const nextGeneration=()=>++state.requestId; const statusLabel=(v)=>({draft:'下書き',published:'公開中',stopped:'停止中'}[v]||v||'');
const errorText = (e, fallback) => { const code=e?.code||e?.message; return ({ENTITLEMENT_REQUIRED:'追加契約が必要です。',DEPARTMENT_INVALID:'配布先の登録情報を確認してください。',PARTICIPANT_COUNT_INVALID:'指定できる参加人数を確認してください。',FORBIDDEN:'この法人では利用できません。',NOT_FOUND:'このカードは利用できません。',SERVICE_UNAVAILABLE:'準備中です。時間をおいて再試行してください。'}[code] || (e?.status===404||e?.status===403?'このカードは利用できません。':e?.status===503?'準備中です。時間をおいて再試行してください。':fallback)); };
function shell(body){ root.setAttribute('aria-busy',state.busy?'true':'false'); root.innerHTML=`<div class="bm-shell"><header class="bm-top"><a href="/business.html?orgId=${encodeURIComponent(state.orgId)}" class="bm-brand" aria-label="Mingle.Cards ホーム"><img src="/assets/mingle-cards-masthead.png" alt="Mingle.Cards" /></a><span class="workspace-name">${esc(state.workspace?.organization?.name || "法人スペース")} </span><span class="spacer"></span><a href="/business.html?orgId=${encodeURIComponent(state.orgId)}">概要</a><a href="/business-activities.html?orgId=${encodeURIComponent(state.orgId)}">アクティビティ</a><a href="/business-marketplace.html?orgId=${encodeURIComponent(state.orgId)}" aria-current="page">法人カード</a></header>${state.error?`<p class="bm-error" role="alert">${esc(state.error)}</p>`:''}${state.status?`<p class="bm-status" role="status">${esc(state.status)}</p>`:''}${body}</div>`;if(state.busy)root.querySelectorAll('button,input,textarea,select').forEach(el=>{el.disabled=true;}); }
function departments(){ return [...new Set((state.departments||[]).filter(Boolean))].sort(); }
function listView(){const sets=state.sets;const ownedEmpty=state.tab==='manage'?'下書き・公開中の専用カードはありません。':'公開された専用カードはありません。';const createHint=admin()&&!state.entitlement?.active?'<p class="bm-error">専用カードの作成・社内配布には追加契約が必要です。料金・課金単位は準備中です。</p>':'';shell(`<h1 tabindex="-1" data-focus>法人マーケットプレイス</h1><p class="bm-subtle">社内で使うカードを公開・管理します。回答や履歴は保存しません。</p><nav class="bm-tabs"><button data-tab="catalog" class="${state.tab==='catalog'?'primary':''}">公開カード</button>${admin()?'<button data-tab="manage" class="'+(state.tab==='manage'?'primary':'')+'">管理</button><button data-new class="primary" '+(state.entitlement?.active===true?'':'disabled')+'>専用カードを作る</button>':''}</nav>${createHint}<section class="bm-owned"><div class="bm-section-head"><div><h2>${state.tab==='manage'?'自社カードの管理':'社内で公開されたカード'}</h2><p class="bm-subtle">部署・チームに配布されたカードです。</p></div></div><div class="bm-list">${sets.length?sets.map(card).join(''):`<p class="bm-subtle bm-empty">${ownedEmpty}</p>`}</div></section><section class="bm-official"><div class="bm-section-head"><div><h2>公式アクティビティ</h2><p class="bm-subtle">無料で使える公式テーマから始められます。</p></div></div><div class="bm-official-grid">${state.official.map(item=>`<div><strong>${esc(item.title||officialNames[item.id]||item.id)}</strong><p class="bm-meta">${esc(item.description||'')} · ${item.cardCount||0}問</p><a href="/business-activities.html?orgId=${encodeURIComponent(state.orgId)}&activity=${encodeURIComponent(item.id)}">開く</a>${admin()?` <button data-copy-official="${esc(item.id)}" ${state.entitlement?.active===true?'':'disabled'}>コピーして編集</button>`:''}</div>`).join('')}</div></section>`);bindList();focus();}
function participantLabel(set){const min=Number(set.minParticipants|| (set.audience==='solo'?1:2));const max=Number(set.maxParticipants||min);return min===max?`${min}人`:`${min}〜${max}人`;}
function card(set){ const canPlay=set.status==='published'&&state.entitlement?.active===true; return `<article class="bm-card"><h2>${esc(set.title)}</h2><p>${esc(set.description||'')}</p><p class="bm-meta">${set.cardCount||0}問 · ${participantLabel(set)} · ${set.visibility==='departments'?'部署限定':'全社'} · ${esc(statusLabel(set.status))}</p><div class="bm-actions">${canPlay?`<button class="primary" data-play="${esc(set.id)}">このカードで遊ぶ</button>`:''}${admin()&&state.tab==='manage'?`<button data-edit-set="${esc(set.id)}">編集</button><button data-duplicate="${esc(set.id)}" ${state.entitlement?.active===true?'':'disabled'}>複製して編集</button>${set.status==='published'?`<button data-stop="${esc(set.id)}">公開停止</button>`:''}`:''}</div></article>`; }
function normalizeEditor(set={}){return {...set,minParticipants:Number(set.minParticipants??set.min??(set.audience==='solo'?1:2)),maxParticipants:Number(set.maxParticipants??set.max??(set.audience==='solo'?1:8)),departments:Array.isArray(set.departments)?set.departments:(Array.isArray(set.targetDepartments)?set.targetDepartments:[]),cards:(Array.isArray(set.cards)?set.cards:[]).map(c=>typeof c==='string'?c:c?.text||'')};}
function form(){ const e=state.editing||{title:'',description:'',audience:'group',minParticipants:2,maxParticipants:8,visibility:'all',departments:[],status:'draft',cards:['']}; e.departments=e.departments||[]; e.cards=e.cards?.length?e.cards:['']; const depts=departments(); const entitlementActive=state.entitlement?.active===true; return `<h1 tabindex="-1" data-focus>${e.id?'専用カードを編集':'専用カードを作る'}</h1><p class="bm-subtle">配布先はメンバー登録の「部署・チーム」情報から選べます。カードには設問だけを保存します。</p>${!entitlementActive?'<p class="bm-error">専用カードの作成・社内配布には追加契約が必要です。料金・課金単位は準備中です。</p>':''}<form class="bm-form" data-form><label>タイトル<input name="title" maxlength="120" value="${esc(e.title)}" required></label><label>説明<textarea name="description" maxlength="500">${esc(e.description)}</textarea></label><div class="bm-counts"><label>最少人数<input name="minParticipants" type="number" min="1" max="8" value="${Number(e.minParticipants||2)}"></label><label>最大人数<input name="maxParticipants" type="number" min="1" max="8" value="${Number(e.maxParticipants||8)}"></label></div><label>配布先<select name="visibility"><option value="all" ${e.visibility==='all'?'selected':''}>全社</option><option value="departments" ${e.visibility==='departments'?'selected':''}>部署・チームを選ぶ</option></select></label><div class="bm-departments">${depts.map(d=>`<label><input type="checkbox" name="department" value="${esc(d)}" ${e.departments.includes(d)?'checked':''}> ${esc(d)}</label>`).join('')||'<span class="bm-subtle">登録済みの部署・チームはありません。</span>'}</div><label>公開状態<select name="status"><option value="draft" ${e.status!=='published'?'selected':''}>下書き</option><option value="published" ${e.status==='published'?'selected':''}>公開</option></select></label><div class="bm-rows">${e.cards.map((text,i)=>`<div class="bm-row"><label>質問${i+1}<textarea name="card" maxlength="1000" required>${esc(typeof text==='string'?text:text.text||'')}</textarea></label>${i?`<button type="button" data-remove="${i}">削除</button>`:''}</div>`).join('')}</div><div class="bm-actions"><button type="button" data-add>質問を追加</button><button class="primary" type="submit" ${state.busy||!entitlementActive?'disabled':''}>保存</button><button type="button" data-cancel>戻る</button></div></form>`; }
function playSetup(){ const s=state.playSetup; const min=Number(s.set.minParticipants|| (s.set.audience==='solo'?1:2)); const max=Number(s.set.maxParticipants||min); const fixed=min===max; const count=Math.max(min,Math.min(max,Number(s.count)||min)); s.count=count; shell(`<section class="bm-play"><h1 tabindex="-1" data-focus>${esc(s.set.title)}</h1><p>参加人数を確認して開始します。回答や履歴は保存しません。</p>${fixed?`<p>参加人数: <strong>${min}人</strong></p>`:`<label>参加人数 <button type="button" data-minus aria-label="人数を減らす" ${count<=min?'disabled':''}>−</button><input data-count type="number" min="${min}" max="${max}" value="${count}"><button type="button" data-plus aria-label="人数を増やす" ${count>=max?'disabled':''}>＋</button></label>`}<div class="bm-actions"><button class="primary" data-confirm-play>開始</button><button data-exit>戻る</button></div></section>`); bindPlaySetup(); }
function play(){ const cards=state.play.cards||[]; const i=state.play.index||0; if(i>=cards.length){ shell(`<section class="bm-play"><h1 tabindex="-1" data-focus>おつかれさまでした</h1><p>回答や履歴は保存していません。</p><button data-exit>一覧へ戻る</button></section>`); bindPlay(); return; } shell(`<section class="bm-play"><p class="bm-progress">${esc(state.play.title)} · ${i+1} / ${cards.length}</p><h1 tabindex="-1" data-focus>質問カード</h1><article class="bm-question">${esc(cards[i].text||cards[i])}</article><div class="bm-actions"><button data-prev ${i?'':'disabled'}>前へ</button><button class="primary" data-next>次のカード</button><button data-pass>パス</button><button data-exit>退出</button></div><p class="bm-subtle">呼び名の入力、回答、履歴の保存はありません。</p></section>`); bindPlay(); }
function focus(){requestAnimationFrame(()=>root.querySelector('[data-focus]')?.focus());}
function render(){ if(state.play)return play(); if(state.playSetup)return playSetup(); if(state.tab==='edit'){shell(form());bindForm();focus();return;} listView(); }
async function load(){
  const request=state.requestId;
  try{
    const me=await accountApi.me();
    if(!fresh(request))return;
    state.user=me?.user||null;
    if(!state.user?.id)throw Object.assign(new Error('ログインが必要です。'),{code:'UNAUTHENTICATED'});
    if(!state.authBound&&typeof accountApi.onAuthStateChange==='function'){
      accountApi.onAuthStateChange((event)=>{if(event==='TOKEN_REFRESHED')return;nextGeneration();state.user=null;state.workspace=null;state.orgId='';state.role='member';state.entitlement=null;state.departments=[];state.sets=[];state.official=[];state.editing=null;state.play=null;state.playSetup=null;state.tab='catalog';state.busy=false;state.error='';state.status='';shell('<p class="loading">読み込み中…</p>');load();});
      state.authBound=true;
    }
    const orgs=(await businessRequest('/organizations')).organizations||[];
    if(!fresh(request))return;
    const wanted=new URLSearchParams(location.search).get('orgId');
    if(wanted){if(!orgs.some(o=>(o.id||o.organizationId)===wanted))throw Object.assign(new Error('この法人にはアクセスできません。'),{code:'FORBIDDEN'});state.orgId=wanted;}
    else state.orgId=orgs[0]?.id||orgs[0]?.organizationId||'';
    if(!state.orgId)throw new Error('組織がありません。');
    const workspace=await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/workspace`);
    if(!fresh(request))return;
    state.workspace=workspace;state.role=workspace.role||'member';
    const payload=await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/card-market`);
    if(!fresh(request))return;
    state.sets=payload.sets||[];state.official=payload.officialActivities||[];state.departments=payload.departments||[];state.entitlement={active:payload.entitlementActive===true,activeUntil:payload.entitlementUntil||null};render();
  }catch(e){if(!fresh(request))return;state.error=e?.code==='UNAUTHENTICATED'?'ログインが必要です。':errorText(e,'法人カードを読み込めませんでした。');shell(`<h1 tabindex="-1" data-focus>法人マーケットプレイス</h1><p>${esc(state.error)}</p><a href="/business.html">企業スペースへ戻る</a>`);focus();}
}function bindList(){
  root.querySelectorAll('[data-tab]').forEach((b)=>b.onclick=()=>{if(state.busy)return;nextGeneration();state.tab=b.dataset.tab;loadOwnerIfNeeded();});
  root.querySelector('[data-new]')?.addEventListener('click',()=>{if(state.busy||state.entitlement?.active!==true)return;nextGeneration();state.editing={title:'',description:'',audience:'group',minParticipants:2,maxParticipants:8,visibility:'all',departments:[],status:'draft',cards:['']};state.tab='edit';render();});
  root.querySelectorAll('[data-copy-official]').forEach(b=>b.onclick=async()=>{if(state.busy||state.entitlement?.active!==true)return;const token=state.requestId;state.busy=true;state.error='';render();try{const r=await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/card-market/official/${encodeURIComponent(b.dataset.copyOfficial)}/copy`,{method:'POST'});if(!fresh(token))return;const set=r.set||r;state.editing=normalizeEditor(set);if(!state.editing.cards.length){const d=await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/card-market/sets/${encodeURIComponent(set.id)}`);if(!fresh(token))return;state.editing=normalizeEditor(d.set||d);}if(!fresh(token))return;state.tab='edit';}catch(e){if(fresh(token))state.error=errorText(e,'公式カードをコピーできませんでした。');}finally{if(fresh(token)){state.busy=false;render();}}});
  root.querySelectorAll('[data-edit-set]').forEach(b=>b.onclick=async()=>{if(state.busy)return;const token=state.requestId;state.busy=true;state.error='';render();try{const r=await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/card-market/sets/${b.dataset.editSet}`);if(!fresh(token))return;const set=r.set||r;state.editing=normalizeEditor(set);if(!state.editing.cards.length)throw new Error('このカードの設問を読み込めませんでした。');state.tab='edit';}catch(e){if(fresh(token))state.error=errorText(e,'編集内容を読み込めませんでした。');}finally{if(fresh(token)){state.busy=false;render();}}});
  root.querySelectorAll('[data-duplicate]').forEach(b=>b.onclick=async()=>{if(state.busy||state.entitlement?.active!==true)return;const source=state.sets.find(s=>s.id===b.dataset.duplicate)||{};const token=state.requestId;state.busy=true;state.error='';render();try{const r=await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/card-market/sets/${b.dataset.duplicate}`,{method:'POST',body:{title:'',description:source.description||'',visibility:source.visibility||'all',departments:source.departments||source.targetDepartments||[]}});if(!fresh(token))return;const set=r.set||r;state.editing=normalizeEditor(set);if(!state.editing.cards.length){const d=await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/card-market/sets/${encodeURIComponent(set.id)}`);if(!fresh(token))return;state.editing=normalizeEditor(d.set||d);}if(!fresh(token))return;state.tab='edit';}catch(e){if(fresh(token))state.error=errorText(e,'複製できませんでした。');}finally{if(fresh(token)){state.busy=false;render();}}});
  root.querySelectorAll('[data-stop]').forEach(b=>b.onclick=async()=>{if(state.busy)return;const token=state.requestId;state.busy=true;state.error='';render();try{await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/card-market/sets/${b.dataset.stop}/stop`,{method:'POST'});if(!fresh(token))return;await loadOwnerIfNeeded(token);}catch(e){if(fresh(token))state.error=errorText(e,'公開停止に失敗しました。');}finally{if(fresh(token)){state.busy=false;render();}}});
  root.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{if(!state.busy)startPlay(b.dataset.play);});
}
async function loadOwnerIfNeeded(token=state.requestId){const request=token;if(!fresh(request))return;try{if(state.tab==='manage'&&admin()){const r=await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/card-market/owner`);if(!fresh(request))return;state.sets=r.sets||[];state.departments=r.departments||state.departments;state.entitlement={active:r.entitlementActive===true,activeUntil:r.entitlementUntil||null};}else if(state.tab==='catalog'){const r=await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/card-market`);if(!fresh(request))return;state.sets=r.sets||[];state.departments=r.departments||state.departments;state.entitlement={active:r.entitlementActive===true,activeUntil:r.entitlementUntil||null};}if(fresh(request))render();}catch(e){if(fresh(request)){state.error=errorText(e,'カード一覧を読み込めませんでした。');render();}}}
function bindForm(){root.querySelector('[data-cancel]')?.addEventListener('click',()=>{if(state.busy)return;nextGeneration();state.tab=admin()?'manage':'catalog';loadOwnerIfNeeded();});root.querySelector('[data-add]')?.addEventListener('click',()=>{if(state.busy)return;readForm();state.editing.cards.push('');render();});root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(state.busy)return;readForm();state.editing.cards.splice(Number(b.dataset.remove),1);render();});root.querySelector('[data-form]')?.addEventListener('submit',async ev=>{ev.preventDefault();if(state.busy||state.entitlement?.active!==true)return;readForm();const token=state.requestId;state.busy=true;state.error='';render();try{const path=state.editing.id?`/organizations/${encodeURIComponent(state.orgId)}/card-market/sets/${state.editing.id}`:`/organizations/${encodeURIComponent(state.orgId)}/card-market/sets`;await businessRequest(path,{method:state.editing.id?'PATCH':'POST',body:{title:state.editing.title,description:state.editing.description,audience:state.editing.audience,minParticipants:state.editing.minParticipants,maxParticipants:state.editing.maxParticipants,visibility:state.editing.visibility,departments:state.editing.departments,status:state.editing.status,cards:state.editing.cards.map(text=>({text}))}});if(!fresh(token))return;state.tab='manage';await loadOwnerIfNeeded(token);}catch(e){if(fresh(token))state.error=errorText(e,'保存できませんでした。');}finally{if(fresh(token)){state.busy=false;render();}}});}function readForm(){if(!state.editing)return;state.editing.title=root.querySelector('[name=title]')?.value ?? state.editing.title;state.editing.description=root.querySelector('[name=description]')?.value||'';state.editing.minParticipants=Number(root.querySelector('[name=minParticipants]')?.value||2);state.editing.maxParticipants=Number(root.querySelector('[name=maxParticipants]')?.value||8);if(state.editing.minParticipants===state.editing.maxParticipants&&state.editing.minParticipants===1)state.editing.audience='solo';else if(state.editing.minParticipants===1)state.editing.audience='both';else state.editing.audience='group';state.editing.visibility=root.querySelector('[name=visibility]')?.value||'all';state.editing.status=root.querySelector('[name=status]')?.value||'draft';state.editing.departments=state.editing.visibility==='all'?[]:[...root.querySelectorAll('[name=department]:checked')].map(x=>x.value);state.editing.cards=[...root.querySelectorAll('[name=card]')].map(x=>x.value);}
async function startPlay(id){if(state.busy)return;const set=state.sets.find(s=>s.id===id);if(!set||state.entitlement?.active!==true)return;nextGeneration();state.playSetup={set,count:Number(set.minParticipants|| (set.audience==='solo'?1:2))};render();}
function bindPlaySetup(){
  const adjust=(delta)=>{if(state.busy)return;const input=root.querySelector('[data-count]');if(!input||input.disabled)return;input.value=Math.max(Number(input.min),Math.min(Number(input.max),Number(input.value)+delta));state.playSetup.count=Number(input.value);};
  root.querySelector('[data-minus]')?.addEventListener('click',()=>adjust(-1));root.querySelector('[data-plus]')?.addEventListener('click',()=>adjust(1));root.querySelector('[data-count]')?.addEventListener('change',e=>{if(state.busy)return;state.playSetup.count=Math.max(Number(e.target.min||1),Math.min(Number(e.target.max||8),Number(e.target.value)||1));});
  root.querySelector('[data-confirm-play]')?.addEventListener('click',async()=>{if(state.busy||state.entitlement?.active!==true)return;const token=state.requestId;const s=state.playSetup;state.busy=true;state.error='';render();try{const mode=s.count===1?'solo':'group';const r=await businessRequest(`/organizations/${encodeURIComponent(state.orgId)}/card-market/sets/${encodeURIComponent(s.set.id)}/play`,{method:'POST',body:{mode,participantCount:s.count}});if(!fresh(token))return;state.play={...(r.session||r),index:0};state.playSetup=null;}catch(e){if(fresh(token))state.error=errorText(e,'カードを開始できませんでした。');}finally{if(fresh(token)){state.busy=false;render();}}});
  root.querySelectorAll('[data-exit]').forEach(b=>b.onclick=()=>{if(state.busy)return;nextGeneration();state.playSetup=null;state.tab='catalog';render();});
}
function bindPlay(){root.querySelector('[data-next]')?.addEventListener('click',()=>{if(state.busy)return;state.play.index++;render();});root.querySelector('[data-prev]')?.addEventListener('click',()=>{if(state.busy)return;state.play.index=Math.max(0,state.play.index-1);render();});root.querySelector('[data-pass]')?.addEventListener('click',()=>{if(state.busy)return;state.play.index++;render();});root.querySelectorAll('[data-exit]').forEach(b=>b.onclick=()=>{if(state.busy)return;nextGeneration();state.play=null;state.tab='catalog';render();});}function bind(){}
initializeBusinessPage(load);
